# Replace only exact Kotlin string literals, avoiding identifiers and URL fragments.
for path in ROOT.rglob("*.kt"):
    original = path.read_text(encoding="utf-8")
    updated = original
    for english, portuguese in TRANSLATIONS.items():
        updated = updated.replace('"' + english + '"', '"' + portuguese + '"')
    if updated != original:
        path.write_text(updated, encoding="utf-8")
print("Portuguese UI translations applied.")
